          var new_time = 3 * evt.layerX / evt.target.getBBox().width;
          root.setCurrentTime(new_time);
    }
}
function on_click_c248eac6ecfa17c3fa25d33ebc01544eb49179e72eaa0dfe555f32229002fbf4f80a1eaa3f4db93727d1a1fdb55d25cc075c4771d6562f216938392b48a19aee(evt) {
